using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using AkarangaBank.Web.Data;
using AkarangaBank.Web.Services;
using AkarangaBank.Web.ViewModels;
namespace AkarangaBank.Web.Controllers;
[Authorize]
public class OperationsController : Controller
{
    private readonly IComptabiliteService _service; private readonly ICurrentUserService _current; private readonly AkarangaBankContext _context;
    public OperationsController(IComptabiliteService service, ICurrentUserService current, AkarangaBankContext context) { _service = service; _current = current; _context = context; }
    [Authorize(Policy="GuichetierOnly")] public async Task<IActionResult> Depot() { await ChargerComptesAsync(); return View(new DepotViewModel()); }
    [HttpPost, ValidateAntiForgeryToken, Authorize(Policy="GuichetierOnly")] public async Task<IActionResult> Depot(DepotViewModel vm) { if (!ModelState.IsValid) { await ChargerComptesAsync(vm.CompteId); return View(vm); } try { var op=await _service.DeposerAsync(vm,await _current.GetUserIdAsync()); TempData["Success"]=$"Dépôt enregistré : {op.Reference}"; return RedirectToAction(nameof(Journal)); } catch(InvalidOperationException e) { ModelState.AddModelError("",e.Message); await ChargerComptesAsync(vm.CompteId); return View(vm); } }
    [Authorize(Policy="GuichetierOnly")] public async Task<IActionResult> Retrait() { await ChargerComptesAsync(); return View(new RetraitViewModel()); }
    [HttpPost, ValidateAntiForgeryToken, Authorize(Policy="GuichetierOnly")] public async Task<IActionResult> Retrait(RetraitViewModel vm) { if (!ModelState.IsValid) { await ChargerComptesAsync(vm.CompteId); return View(vm); } try { var op=await _service.RetirerAsync(vm,await _current.GetUserIdAsync()); TempData["Success"]=$"Retrait enregistré : {op.Reference}"; return RedirectToAction(nameof(Journal)); } catch(InvalidOperationException e) { ModelState.AddModelError("",e.Message); await ChargerComptesAsync(vm.CompteId); return View(vm); } }
    [Authorize(Policy="GuichetierOnly")] public async Task<IActionResult> Virement() { await ChargerComptesAsync(); return View(new VirementViewModel()); }
    [HttpPost, ValidateAntiForgeryToken, Authorize(Policy="GuichetierOnly")] public async Task<IActionResult> Virement(VirementViewModel vm) { if (!ModelState.IsValid) { await ChargerComptesAsync(vm.CompteSourceId,vm.CompteDestinationId); return View(vm); } try { var op=await _service.VirerAsync(vm,await _current.GetUserIdAsync()); TempData["Success"]=$"Virement effectué : {op.Reference}"; return RedirectToAction(nameof(Journal)); } catch(InvalidOperationException e) { ModelState.AddModelError("",e.Message); await ChargerComptesAsync(vm.CompteSourceId,vm.CompteDestinationId); return View(vm); } }
    [Authorize(Policy="GuichetierOnly")] public async Task<IActionResult> Journal(DateTime? du, DateTime? au, string? typeOperation, int page=1) { var agency=User.IsInRole("admin") ? (int?)null : await _current.GetAgenceIdAsync(); var vm=await _service.GetJournalAsync(du,au,typeOperation,page,20,agency); return View(vm); }
    [Authorize(Roles="client")] public async Task<IActionResult> VirementPersonnel() { var id=await _current.GetUserIdAsync(); var user=await _context.Users.AsNoTracking().SingleAsync(u=>u.Id==id); var source=await _context.Comptes.AsNoTracking().Include(c=>c.Client).Where(c=>!c.EstCompteInterne && c.Statut=="Actif" && c.AgenceId==user.AgenceId && c.ClientId==user.ClientId).OrderBy(c=>c.NumeroCompte).Select(c=>new {c.Id,Libelle=c.NumeroCompte+" — "+c.Client!.Nom+" "+c.Client.Prenom}).ToListAsync(); ViewBag.ComptesSource=new SelectList(source,"Id","Libelle"); return View(new VirementViewModel()); }
    [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="client")] public async Task<IActionResult> VirementPersonnel(VirementViewModel vm) { var id=await _current.GetUserIdAsync(); var user=await _context.Users.AsNoTracking().SingleAsync(u=>u.Id==id); if(!user.ClientId.HasValue || !await _context.Comptes.AnyAsync(c=>c.Id==vm.CompteSourceId && c.ClientId==user.ClientId && !c.EstCompteInterne)) return Forbid(); vm.CompteDestinationId=await _context.Comptes.AsNoTracking().Where(c=>c.NumeroCompte==vm.NumeroCompteDestination && c.AgenceId==user.AgenceId && c.Statut=="Actif" && !c.EstCompteInterne).Select(c=>c.Id).FirstOrDefaultAsync(); if(vm.CompteDestinationId==0) ModelState.AddModelError(nameof(vm.NumeroCompteDestination),"Compte destinataire introuvable dans votre agence."); if(!ModelState.IsValid) { await VirementPersonnel(); return View(vm); } try { var op=await _service.VirerAsync(vm,id); TempData["Success"]=$"Virement effectué : {op.Reference}"; return RedirectToAction("Index","Comptes"); } catch(InvalidOperationException e) { ModelState.AddModelError("",e.Message); await VirementPersonnel(); return View(vm); } }
    public async Task<IActionResult> Releve(int id) { var vm=await _service.GetReleveAsync(id); if(vm is null)return NotFound(); if(!User.IsInRole("admin")) { var userId=await _current.GetUserIdAsync(); var user=await _context.Users.AsNoTracking().FirstOrDefaultAsync(u=>u.Id==userId); if(user is null)return Forbid(); if(User.IsInRole("client")) { if(!user.ClientId.HasValue || vm.Compte.ClientId!=user.ClientId) return Forbid(); } else if(vm.Compte.AgenceId!=user.AgenceId) return Forbid(); } return View(vm); }
    [Authorize(Policy="AdminOnly")] public async Task<IActionResult> ControleEquilibre() { ViewBag.EstEquilibre=await _service.VerifierEquilibreGlobalAsync(); return View(); }
    private async Task ChargerComptesAsync(int? sourceId=null,int? destinationId=null) { var agency=await _current.GetAgenceIdAsync(); var accounts=await _context.Comptes.AsNoTracking().Include(c=>c.Client).Where(c=>!c.EstCompteInterne && c.Statut=="Actif" && c.AgenceId==agency).OrderBy(c=>c.NumeroCompte).Select(c=>new {c.Id, Libelle=c.NumeroCompte+" — "+c.Client!.Nom+" "+c.Client.Prenom}).ToListAsync(); ViewBag.Comptes=new SelectList(accounts,"Id","Libelle",sourceId); ViewBag.ComptesSource=new SelectList(accounts,"Id","Libelle",sourceId); ViewBag.ComptesDestination=new SelectList(accounts,"Id","Libelle",destinationId); }
}
